    alias = schema_editor.connection.alias
    Entry = apps.get_model("core", "ProviderConfigEntry")
    ProviderConfig = apps.get_model("core", "ProviderConfig")
    OverrideConfig = apps.get_model("core", "NotificationOverrideConfig")

    for config in ProviderConfig.objects.using(alias).all():
        system_id = None
        if not config.is_available_by_default:
            system_id = OverrideConfig.objects.using(alias).filter(
                provider_config_id=config.id,
                override_provider__override__organization_id__isnull=True,
            ).values_list("override_provider__override__system_id", flat=True).first()
        Entry.objects.using(alias).filter(provider_config_id=config.id).update(
            provider_id=config.provider_id,
            system_id=system_id,
        )
    flush_constraint_checks(apps, schema_editor)


